// Add Skill Fruit trees from exported World Partition cells.
//
//   node extract/merge-skillfruit.mjs
//
// Unlike effigies (all in one coarse cell), skill fruit trees sit roughly one
// per fine-grained L0 cell — 47 trees across 46 cells. work/skillfruit-cells.txt
// lists exactly which, generated by merge-locations.mjs from the persistent
// level's SubObjectsToCellRemapping index.
//
// This scans whatever cells are present rather than demanding all of them, so
// it can be re-run as more are exported and reports what's still missing.
//
// Skill fruit trees respawn, so the game keeps no per-instance record of them:
// these are reference markers, ticked by hand.
//
// © Void Possum

import fs from 'node:fs';
import path from 'node:path';

const CELLS = 'Output/Exports/Pal/Content/Pal/Maps/MainWorld_5/PL_MainWorld5/_Generated_';
const WANTED = 'work/skillfruit-cells.txt';
const MATCH = /^BP_PalMapObjectSpawner_SkillFruits_(.+?)_C$/;

const indexOf = objectPath => Number(String(objectPath).split('.').pop());

function locationOf(actor, file) {
  const ref = actor.Properties?.RootComponent || actor.Properties?.DefaultSceneRoot
    || actor.Properties?.RootSceneComponent;
  if (!ref?.ObjectPath) return null;
  const loc = file[indexOf(ref.ObjectPath)]?.Properties?.RelativeLocation;
  return loc ? { x: loc.X, y: loc.Y, z: loc.Z ?? 0 } : null;
}

const titleCase = s => String(s).replace(/([a-z])([A-Z])/g, '$1 $2').replace(/_/g, ' ').trim();

if (!fs.existsSync(CELLS)) {
  console.error(`No exported cells at ${CELLS}\nExport them from FModel first — see EXTRACTING.md.`);
  process.exit(1);
}

const wanted = fs.existsSync(WANTED)
  ? fs.readFileSync(WANTED, 'utf8').split(/\r?\n/).filter(Boolean)
  : null;

const present = new Set(fs.readdirSync(CELLS).filter(f => f.endsWith('.json')).map(f => f.replace(/\.json$/, '')));
const scan = wanted ? wanted.filter(c => present.has(c)) : [...present];

console.log(`cells available: ${scan.length}${wanted ? ` of ${wanted.length} needed` : ''}`);
if (!scan.length) {
  console.error('None of the required cells are exported yet — nothing to do.');
  process.exit(1);
}

const data = JSON.parse(fs.readFileSync('app/data/markers.json', 'utf8'));
data.markers = data.markers.filter(m => m.category !== 'skillFruit');
data.categories = data.categories.filter(c => c.id !== 'skillFruit');

const seen = new Set();
let n = 0;
for (const cell of scan) {
  const file = JSON.parse(fs.readFileSync(path.join(CELLS, `${cell}.json`), 'utf8'));
  for (const actor of file) {
    const m = MATCH.exec(actor.Type || '');
    if (!m) continue;
    const loc = locationOf(actor, file);
    if (!loc) continue;
    // No instance id on these, so key on rounded position — stable across runs
    // and naturally de-duplicates a tree indexed into two overlapping cells.
    const key = `${Math.round(loc.x)}_${Math.round(loc.y)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    data.markers.push({
      id: `skillFruit:${key}`,
      category: 'skillFruit',
      key,
      label: `Skill Fruit Tree (${titleCase(m[1])})`,
      x: Math.round(loc.x), y: Math.round(loc.y), z: Math.round(loc.z),
    });
    n++;
  }
}

data.categories.push({ id: 'skillFruit', name: 'Skill Fruit', saveFlag: null });
data.generatedAt = new Date().toISOString();
fs.writeFileSync('app/data/markers.json', JSON.stringify(data));

console.log(`skill fruit trees: ${n}`);
if (wanted) {
  const missing = wanted.filter(c => !present.has(c));
  if (missing.length) {
    console.log(`\nstill missing ${missing.length} cell(s) — export these and re-run:`);
    for (const c of missing.slice(0, 10)) console.log(`  ${c}`);
    if (missing.length > 10) console.log(`  … and ${missing.length - 10} more (see ${WANTED})`);
  }
}
console.log(`\nwrote app/data/markers.json — ${data.markers.length} markers`);
